{
  "functions": [
    {
      "source": "functions",
      "codebase": "default",
      "ignore": [
        "node_modules",
        ".git",
        "firebase-debug.log",
        "firebase-adminsdk-*.json",
        "serviceAccountKey.json"
      ]
    }
  ],
  "hosting": {
    "site": "fixgo-44e4d",
    "public": ".",

      "ignore": [
        "firebase.json",
        "**/.*",
        "**/node_modules/**",
        "node_modules/**",
        "functions/**",
        "tests/**",
        "repo_sandbox/**",
        "build/**",
        ".gradle/**",
        ".firebase/**",
        ".vscode/**",
        "package.json",
        "package-lock.json",
        "build.gradle",
        "settings.gradle",
        "gradle.properties",
        "gradle/**",
        "gradlew",
        "gradlew.bat",
        "vercel.json",
        "activos_uxmal39.json",
        "mantenimiento_edificio.json",
        "android.keystore",
        "*.keystore",
        "*.jks",
        "*.pem",
        "*.key",
        "*.p12",
        "*.apk",
        "*.aab",
        "*.idsig",
        "serviceAccountKey.json",
        "firebase-adminsdk-*.json",
        "google-services.json",
        "GoogleService-Info.plist",
        "*.md"
      ],

    "cleanUrls": false,
    "trailingSlash": false,

    "rewrites": [
  {
    "source": "/api/**",
    "function": "api"
  }
],

    "headers": [
      {
        "source": "**/*.html",
        "headers": [
          {
            "key": "Cache-Control",
            "value": "no-cache, no-store, must-revalidate"
          }
        ]
      },

      {
        "source": "/gestia-core/**",
        "headers": [
          {
            "key": "Cache-Control",
            "value": "no-cache, no-store, must-revalidate"
          }
        ]
      },

      {
        "source": "/modules/**",
        "headers": [
          {
            "key": "Cache-Control",
            "value": "no-cache, no-store, must-revalidate"
          }
        ]
      },

      {
        "source": "/assets/**",
        "headers": [
          {
            "key": "Cache-Control",
            "value": "public,max-age=3600"
          }
        ]
      },

      {
        "source": "/sw.js",
        "headers": [
          {
            "key": "Cache-Control",
            "value": "no-cache, no-store, must-revalidate"
          },
          {
            "key": "Service-Worker-Allowed",
            "value": "/"
          }
        ]
      },

      {
        "source": "/manifest.json",
        "headers": [
          {
            "key": "Cache-Control",
            "value": "no-cache, no-store, must-revalidate"
          },
          {
            "key": "Content-Type",
            "value": "application/manifest+json"
          }
        ]
      },

      {
        "source": "**/*.js",
        "headers": [
          {
            "key": "Cache-Control",
            "value": "no-cache"
          }
        ]
      }
    ]
  }
}
